/* Loads the rebuilt interface, approved oriental visual system, then the original offline JSZip build. */
(() => {
  const VERSION = "2026-08-05-r9-approved";

  const addStyle = (href, dataName) => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = `${href}?v=${VERSION}`;
    link.dataset[dataName] = "true";
    document.head.appendChild(link);
  };

  const addScript = (src, dataName) => {
    const script = document.createElement("script");
    script.src = `${src}?v=${VERSION}`;
    script.async = false;
    script.dataset[dataName] = "true";
    document.head.appendChild(script);
  };

  const rebuiltUi = document.createElement("script");
  rebuiltUi.src = `./ui-rebuild.js?v=${VERSION}`;
  rebuiltUi.async = false;
  rebuiltUi.addEventListener("load", () => {
    addStyle("./theme-oriental-r5.css", "tabletRefinements");
    addStyle("./theme-oriental-r6.css", "focusedRefinements");
    addStyle("./theme-oriental-r8.css", "precisionRefinements");
    addStyle("./theme-actions-r8.css", "singleActionRules");
    addStyle("./theme-oriental-r9.css", "approvedOrientalVisualSystem");

    addScript("./ui-refinements-r6.js", "refinementScript");
    addScript("./ui-icons-r8.js", "localIconScript");
    addScript("./ui-deduplicate-r8.js", "deduplicateScript");
    addScript("./ui-polish-r9.js", "approvedPolishScript");
  });
  document.head.appendChild(rebuiltUi);

  document.write('<script src="vendor/jszip-core.min.js"><\/script>');
})();
